import "./Gallery.css";

const galleryImages = [
  { title: "Home Cleaning", img: "https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?w=800" },
  { title: "Gardening", img: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800" },
  { title: "Plumbing Work", img: "https://images.unsplash.com/photo-1563453392212-326f5e854473?w=800" },
  { title: "Electrical Work", img: "https://images.unsplash.com/photo-1590412255804-079f4cde2f93?w=800" },
  { title: "Painting Work", img: "https://images.unsplash.com/photo-1503387762-592deb58ef4e?w=800" },
  { title: "Carpenter Work", img: "https://images.unsplash.com/photo-1519710164239-da123dc03ef4?w=800" },
  { title: "Beauty & Makeup", img: "https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=800" },
  { title: "Massage Therapy", img: "https://images.unsplash.com/photo-1611078489935-0cb9640b86c7?w=800" },
  { title: "AC Repair", img: "https://images.unsplash.com/photo-1581090700227-1e37b190418e?w=800" },
  { title: "Pest Control", img: "https://images.unsplash.com/photo-1620121692029-d088224ddc74?w=800" },
  { title: "Pet Care", img: "https://images.unsplash.com/photo-1517849845537-4d257902454a?w=800" },
  { title: "Laptop Repair", img: "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=800" }
];

export default function Gallery() {
  return (
    <div className="gallery-container">
      <h2 className="gallery-title">Gallery</h2>

      <div className="gallery-grid">
        {galleryImages.map((g, i) => (
          <div className="gallery-card" key={i}>
            <img src={g.img} alt={g.title} />
            <p>{g.title}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
